export function estadisticas(notas) {
  const ordenadas = notas.sort();
  const suma = notas.reduce((acc, n) => acc + n, 0);
  const promedio = suma / notas.length;

  const mitad = Math.floor(ordenadas.length / 2);
  const mediana = ordenadas.length % 2 === 0
    ? (ordenadas[mitad - 1] + ordenadas[mitad]) / 2
    : ordenadas[mitad];

  const aprobados = notas.filter((n) => n >= 11).length;
  const x = Math.max(...notas);

  return {
    promedio,
    mediana,
    aprobados,
    maxima: x,
    minima: ordenadas[0],
  };
}
